<?php require __DIR__.'/bootstrap.php';require_login();$keys=['phone'=>'Phone','phone_digits'=>'Phone digits / WhatsApp','email'=>'Company email','youtube'=>'YouTube URL','facebook'=>'Facebook URL','tiktok'=>'TikTok URL','website'=>'Website','business_hours'=>'Business hours'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$st=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($keys as $k=>$l)$st->execute([$k,trim((string)($_POST[$k]??''))]);flash('success','Settings saved.');header('Location: settings.php');exit;}$s=settings();$pageTitle='Settings';$active='settings';require __DIR__.'/_header.php';?><p class="eyebrow">SETTINGS</p><h1>Contact & social links</h1><section class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><?php foreach($keys as $k=>$l):?><label><?=h($l)?><input name="<?=h($k)?>" value="<?=h($s[$k]??'')?>"></label><?php endforeach;?><button>Save settings</button></form></section><?php require __DIR__.'/_footer.php';
